impl Pattern {
    pub(crate) fn definition(self) -> PatternDefinition {
        match self {
            Pattern::Constants => PatternDefinition {
                act: Act::Match(scopes![S::ConstSource]),
                captures: &[],
                nested: &[],
            },
            Pattern::Keywords | Pattern::Commands => PatternDefinition {
                act: Act::Match(scopes![S::Kw]),
                captures: &[],
                nested: &[],
            },
            Pattern::Variables
            | Pattern::TargetVariables
            | Pattern::CmakeVariables
            | Pattern::CxxFlags => PatternDefinition {
                act: Act::Match(scopes![S::VarSource]),
                captures: &[],
                nested: &[],
            },
            Pattern::Expansion | Pattern::EnvExpansion => PatternDefinition {
                act: Act::Match(scopes![S::StorSource]),
                captures: &[],
                nested: &[],
            },
            Pattern::BracketComment => PatternDefinition {
                act: Act::Begin(Rule::BracketComment),
                captures: &[],
                nested: &[],
            },
            Pattern::BracketCommentEnd
            | Pattern::BracketArgumentEnd
            | Pattern::EscapedStringEnd
            | Pattern::StringEnd => PatternDefinition {
                act: Act::End,
                captures: &[],
                nested: &[],
            },
            Pattern::BracketCommentAt0
            | Pattern::BracketArgumentAt0
            | Pattern::EscapedStringAt0
            | Pattern::StringAt0 => PatternDefinition {
                act: Act::Match(scopes![S::ConstCharacterEscapeBare]),
                captures: &[],
                nested: &[],
            },
            Pattern::BracketArgument => PatternDefinition {
                act: Act::Begin(Rule::BracketArgument),
                captures: &[],
                nested: &[],
            },
            Pattern::LineComment => PatternDefinition {
                act: Act::Match(scopes![S::CmtSource]),
                captures: &[],
                nested: &[],
            },
            Pattern::CacheProperties
            | Pattern::SourceProperties
            | Pattern::TestProperties
            | Pattern::DirectoryProperties
            | Pattern::GlobalProperties
            | Pattern::TargetProperties => PatternDefinition {
                act: Act::Match(scopes![S::EntSource]),
                captures: &[],
                nested: &[],
            },
            Pattern::EscapedString => PatternDefinition {
                act: Act::Begin(Rule::EscapedString),
                captures: &[],
                nested: &[],
            },
            Pattern::String => PatternDefinition {
                act: Act::Begin(Rule::String),
                captures: &[],
                nested: &[],
            },
            Pattern::BuildName => PatternDefinition {
                act: Act::Match(scopes![S::InvDeprecatedSource]),
                captures: &[],
                nested: &[],
            },
        }
    }
}

